def editor(acciones):
    pila = []
    for a in acciones:
        if a == "deshacer":
            if pila:
                pila.pop()
        else:
            pila.append(a.split(" ", 1)[1])
    return "".join(pila)

editor(["escribir ho", "escribir la", "escribir xx", "deshacer"])  # 'hola'

